    print("Testing TreeNode functionality...")

    # Create nodes
    root = TreeNode()
    child1 = TreeNode()
    child2 = TreeNode()

    # Test parent/child relationships
    root.children = {"child1": child1, "child2": child2}

    print(f"Root has {len(root.children)} children")
    print(f"Child1 parent is root: {child1.parent is root}")
    print(f"Root is root: {root.is_root}")
    print(f"Child1 is leaf: {child1.is_leaf}")
    print(f"Root parents count: {len(root.parents)}")
    print(f"Child1 parents count: {len(child1.parents)}")

    # Test orphaning
    child1.orphan()
    print(f"After orphaning - Child1 parent is None: {child1.parent is None}")
    print(f"Root now has {len(root.children)} children")

    print("All tests passed!")

